css:
html, body { background: #111 !important; }
#hnmain { background: #181818 !important; }
td[bgcolor="#ff6600"] { background: #5a2a0c !important; }
td[bgcolor="#ff6600"] a, .pagetop { color: #f2c6a8 !important; }

body, td, .title, .commtext, .comment { color: #d4d4d4 !important; }
.titleline > a:link { color: #ececec !important; }
.titleline > a:visited { color: #8a8a8a !important; }
.subtext, .subline, .comhead, .sitebit, .sitestr, .age a, .hnuser, .navs a { color: #8a8a8a !important; }
.commtext a { color: #f0a070 !important; }
.c5a, .c73, .c82, .c88, .c9c, .cae, .cbe, .cce, .cdd { color: #6f6f6f !important; }

.votearrow { filter: invert(.75); }
input, textarea, select {
  background: #222;
  color: #ddd;
  border: 1px solid #3a3a3a;
}
